/* Blender-made model library (GLB, zlib-deflated, base64). Built in Blender 5.1 from the user's President Office style + school set. */
const RA_GLB_Z="";

/* =====================================================================
   BLENDER MODELS: swap the primitive placeholders for the Blender set.
   The GLB is embedded (deflated + base64), inflated with DecompressionStream, parsed by GLTFLoader.
   If anything fails the primitive versions simply stay.
   ===================================================================== */
const MODEL_MAP={
 chair:{m:'chair',ry:Math.PI,tint:3,def:0x2f4f6f}, desk:{m:'desk'}, bed:{m:'bed',tint:3,def:0x3a6ea5}, shelf:{m:'shelf',tint:3,def:0x8a6a4a},
 locker:{m:'locker',tint:3,def:0x4a6fa5}, sofa:{m:'sofa',ry:Math.PI,tint:3,def:0x6c5ce7}, table:{m:'table'}, cabinet:{m:'cabinet'},
 plant:{m:'big_plant',s:.8}, computer:{m:'monitor',y:.76}, washer:{m:'washer'}, piano:{m:'piano'}, tv:{m:'tv'},
 crate:{m:'crate',sArg:2}, tree:{m:'tree',sArg:2,tint:3,def:0xff6b4a}, bench:{m:'bench',ry:Math.PI}, lamp:{m:'lamp'},
 exec_desk:{m:'exec_desk'},exec_chair:{m:'exec_chair'},visitor_chair:{m:'visitor_chair'},sofa_white:{m:'sofa_white'},armchair:{m:'armchair'},
 coffee_table:{m:'coffee_table'},side_table:{m:'side_table'},table_lamp:{m:'table_lamp'},monitor:{m:'monitor'},big_plant:{m:'big_plant'},
 sideboard:{m:'sideboard'},globe:{m:'globe'},artwork:{m:'artwork'},rug_exec:{m:'rug_exec'}};
const MODELS={};let MODELS_READY=false;
function prepModel(o){o.traverse(c=>{if(!c.isMesh)return;c.castShadow=true;c.receiveShadow=true;
 const ms=Array.isArray(c.material)?c.material:[c.material];ms.forEach(m=>{if(m.metalness>.3){m.metalness=.25;m.roughness=Math.max(.35,m.roughness);}m.envMapIntensity=1;});});return o;}
const TINT_CACHE={};
function tinted(model,hex){const key=model.name+'|'+hex;if(TINT_CACHE[key])return TINT_CACHE[key].clone();
 const o=model.clone(true);o.traverse(c=>{if(!c.isMesh)return;const fix=m=>{if(!/tint/.test(m.name))return m;const n=m.clone();n.color.setHex(hex).convertSRGBToLinear();return n;};
  c.material=Array.isArray(c.material)?c.material.map(fix):fix(c.material);});TINT_CACHE[key]=o;return o.clone();}
function applyModels(){let n=0;MODEL_SLOTS.forEach(sl=>{const spec=MODEL_MAP[sl.kind];if(!spec||sl.done)return;const base=MODELS['M_'+spec.m];if(!base)return;
 const hex=spec.tint!==undefined?(sl.args[spec.tint]!==undefined?sl.args[spec.tint]:spec.def):null;
 const o=hex!==null?tinted(base,hex):base.clone();o.position.set(0,spec.y||0,0);o.rotation.set(0,spec.ry||0,0);
 const s=(spec.s||1)*(spec.sArg!==undefined&&typeof sl.args[spec.sArg]==='number'?sl.args[spec.sArg]:1);o.scale.setScalar(s);
 sl.g.children.slice().forEach(c=>{if(!(c.userData&&c.userData.keep))c.visible=false;});sl.g.add(o);sl.done=1;n++;});return n;}
async function loadModels(){try{
 if(!THREE.GLTFLoader||typeof DecompressionStream==='undefined')return;
 const bin=Uint8Array.from(atob(RA_GLB_Z),c=>c.charCodeAt(0));
 const buf=await new Response(new Blob([bin]).stream().pipeThrough(new DecompressionStream('deflate'))).arrayBuffer();
 const gl=await new Promise((res,rej)=>new THREE.GLTFLoader().parse(buf,'',res,rej));
 gl.scene.children.slice().forEach(c=>{c.position.set(0,0,0);MODELS[c.name]=prepModel(c);});
 MODELS_READY=true;const n=applyModels();window.MODELS_SWAPPED=n;
}catch(e){console.warn('Model library not loaded:',e&&e.message);}}
loadModels();
